from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, expire_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            expire_time = t + ttl

            if key in cache:
                _, old_expire = cache[key]
                if old_expire <= t:
                    # expired, treat as absent
                    del cache[key]
                else:
                    # still valid, update and move to end
                    del cache[key]
                    cache[key] = (value, expire_time)
                    continue

            # key not in cache (or was removed due to expiry)
            if len(cache) >= capacity:
                cache.popitem(last=False)  # evict LRU

            cache[key] = (value, expire_time)

        elif op[0] == 'get':
            _, t, key = op

            if key in cache:
                value, expire_time = cache[key]
                if expire_time <= t:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    # valid, move to end (most recently used)
                    del cache[key]
                    cache[key] = (value, expire_time)
                    results.append(value)
            else:
                results.append(-1)

    return results

